import { unstable_cache } from 'next/cache'

// In-memory store for demo purposes. In a real app this would be a database.
const store: Post[] = [
  { id: 1, title: 'Hello world', body: 'My first post' },
]

export type Post = { id: number; title: string; body: string }

/**
 * Cached read of the posts list, tagged with "posts".
 *
 * Associating the "posts" tag with this cached function lets a Server Action
 * purge exactly this data on demand via `revalidateTag('posts')`. After
 * invalidation, the next request re-runs this function and waits for the
 * fresh result instead of serving stale cached content.
 */
export const getPosts = unstable_cache(
  async (): Promise<Post[]> => [...store],
  ['posts'],
  { tags: ['posts'] },
)

/**
 * Mutates the underlying store. This must NOT be cached — it writes data.
 * Callers (Server Actions) are responsible for invalidating the "posts"
 * cache tag afterwards so readers see the new state.
 */
export function addPost(title: string, body: string): Post {
  const id = store.length ? Math.max(...store.map((p) => p.id)) + 1 : 1
  const post: Post = { id, title, body }
  store.push(post)
  return post
}

