'use server'

import { revalidateTag } from 'next/cache'
import { addPost } from '@/lib/posts'

/**
 * Server Action that creates a new post and invalidates the "posts" cache tag.
 *
 * `revalidateTag('posts')` purges every cache entry associated with the
 * "posts" tag. Unlike time-based revalidation (which may serve stale content
 * while revalidating in the background), this guarantees the next page load
 * waits for fresh data to be fetched, so the user never sees the old list.
 */
export async function createPost(formData: FormData) {
  const title = String(formData.get('title') ?? '').trim()
  const body = String(formData.get('body') ?? '').trim()

  if (!title) {
    return
  }

  addPost(title, body)

  // Purge the "posts" cache tag so the next read re-fetches fresh data.
  revalidateTag('posts')
}

